def safe_upload_path(upload_dir: str, filename: str) -> str:
    if not os.path.isabs(filename):
        filename = os.path.join(upload_dir, filename)
    if os.path.abspath(filename).startswith(os.path.abspath(upload_dir)):
        return filename
    else:
        raise ValueError("Filename would escape upload directory")
